import { useState } from 'react'
import { studyAidFromFile } from '../api.ts'
import type { QuizQuestion, StudyAid as StudyAidResult } from '../api.ts'

// summary + practice quiz for one uploaded file, generated by google gemini
function StudyAid({ file }: { file: File }) {
  const [aid, setAid] = useState<StudyAidResult | null>(null)
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(false)

  async function generate() {
    setLoading(true)
    setError('')
    try {
      setAid(await studyAidFromFile(file))
    } catch (e) {
      setError((e as Error).message)
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="mt-3 border-t border-zinc-200 pt-3 dark:border-zinc-700">
      {!aid && (
        <button
          onClick={generate}
          disabled={loading}
          className="rounded-md bg-amber-500 px-3 py-1.5 text-sm font-semibold text-white hover:bg-amber-600 disabled:opacity-60"
        >
          {loading ? 'reading your notes…' : 'summarize + quiz me'}
        </button>
      )}
      {error && <p className="mt-2 text-sm text-red-600 dark:text-red-400">{error}</p>}

      {aid && (
        <div className="flex flex-col gap-4 text-sm">
          <p className="text-xs text-zinc-500">
            generated by google gemini from your file. ai can make mistakes, so check it against your
            notes.
          </p>
          <div>
            <h4 className="mb-1 font-semibold">summary</h4>
            <p className="text-zinc-700 dark:text-zinc-300">{aid.summary}</p>
          </div>
          <div>
            <h4 className="mb-1 font-semibold">key points</h4>
            <ul className="list-disc space-y-1 pl-5 text-zinc-700 dark:text-zinc-300">
              {aid.key_points.map((point) => (
                <li key={point}>{point}</li>
              ))}
            </ul>
          </div>
          <div>
            <h4 className="mb-2 font-semibold">practice quiz</h4>
            <ol className="flex flex-col gap-4">
              {aid.quiz.map((question, index) => (
                <Question key={question.question} number={index + 1} question={question} />
              ))}
            </ol>
          </div>
        </div>
      )}
    </div>
  )
}

function Question({ number, question }: { number: number; question: QuizQuestion }) {
  const [picked, setPicked] = useState<number | null>(null)
  const answered = picked !== null

  return (
    <li>
      <p className="mb-2 font-medium">
        {number}. {question.question}
      </p>
      <div className="flex flex-col gap-1.5">
        {question.options.map((option, index) => {
          const correct = index === question.answer_index
          let style = 'border-zinc-200 hover:bg-zinc-100 dark:border-zinc-700 dark:hover:bg-zinc-800'
          if (answered && correct) style = 'border-emerald-400 bg-emerald-50 dark:bg-emerald-950/40'
          else if (answered && index === picked) style = 'border-orange-400 bg-orange-50 dark:bg-orange-950/40'
          return (
            <button
              key={option}
              disabled={answered}
              onClick={() => setPicked(index)}
              className={`rounded-md border px-3 py-2 text-left ${style}`}
            >
              {option}
              {answered && correct && ' ✓'}
            </button>
          )
        })}
      </div>
      {answered && <p className="mt-2 text-zinc-600 dark:text-zinc-400">{question.explanation}</p>}
    </li>
  )
}

export default StudyAid
